95	
96	    public override void OnExit()
97	    {
98	        _bus.Off<PlayerFellMessage>(OnPlayerFell);
99	    }
100	
101	    void OnPlayerFell(PlayerFellMessage _)
102	        => _ctrl.ChangeState(GameplayCtrl.State.Lose);
103	}
