138	    public void AddJump() => JumpCount.Current++;
139	}
140	
141	// View
142	public class ScoreUI : MonoBehaviour
143	{
144	    [Inject] private ScoreService _score;
145	
146	    void OnEnable()  => _score.JumpCount.On(UpdateUI);
147	    void OnDisable() => _score.JumpCount.Off(UpdateUI);
